function nqSolve(n, limit){
  if(!Number.isInteger(n)||n<1||n>13) return { value:null, error:'N 须为 1-13 的整数' };
  var cap=(limit===undefined)?100:limit;
  var sols=[], cols=[], nodes=0;
  var colUsed={}, d1={}, d2={};
  function bt(row){
    if(row===n){ if(sols.length<cap) sols.push(cols.slice()); return; }
    for(var c=0;c<n;c++){
      if(colUsed[c]||d1[row-c]||d2[row+c]) continue;
      nodes++;
      colUsed[c]=1; d1[row-c]=1; d2[row+c]=1; cols.push(c);
      bt(row+1);
      cols.pop(); delete colUsed[c]; delete d1[row-c]; delete d2[row+c];
      if(sols.length>=cap && cap>0 && countAll===false) return;
    }
  }
  var countAll=true;
  var total=0;
  // full count pass (fast, no storage)
  (function cnt(row){
    if(row===n){ total++; return; }
    for(var c=0;c<n;c++){
      if(colUsed[c]||d1[row-c]||d2[row+c]) continue;
      colUsed[c]=1; d1[row-c]=1; d2[row+c]=1;
      cnt(row+1);
      delete colUsed[c]; delete d1[row-c]; delete d2[row+c];
    }
  })(0);
  countAll=false;
  bt(0);
  return { value:{ n:n, total:total, solutions:sols, nodes:nodes }, error:null };
}
function nqValidate(cols){
  if(!Array.isArray(cols)||!cols.length) return false;
  var n=cols.length;
  for(var i=0;i<n;i++){
    if(!Number.isInteger(cols[i])||cols[i]<0||cols[i]>=n) return false;
    for(var j=i+1;j<n;j++){
      if(cols[i]===cols[j]) return false;
      if(Math.abs(cols[i]-cols[j])===Math.abs(i-j)) return false;
    }
  }
  return true;
}
function nqCounts(maxN){
  var out=[];
  for(var n=1;n<=maxN;n++) out.push({ n:n, count:nqSolve(n, 0).value.total });
  return out;
}
function nqSvg(cols){
  var n=cols.length, C=Math.max(18, Math.min(44, Math.floor(400/n)));
  var W=n*C+4, H=n*C+4;
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  for(var y=0;y<n;y++) for(var x=0;x<n;x++){
    s+='<rect x="'+(x*C+2)+'" y="'+(y*C+2)+'" width="'+C+'" height="'+C+'" fill="'+((x+y)%2?'#141417':'#1A1B1E')+'"/>';
  }
  for(var r=0;r<n;r++){
    var cx=cols[r]*C+2+C/2, cy=r*C+2+C/2;
    s+='<circle cx="'+cx+'" cy="'+cy+'" r="'+(C*0.32)+'" fill="#5E6AD2" stroke="#A78BFA" stroke-width="1.5"/>';
    s+='<text x="'+cx+'" y="'+(cy+C*0.13)+'" text-anchor="middle" font-size="'+(C*0.38)+'" fill="#FFFFFF" font-family="system-ui,sans-serif">♛</text>';
  }
  s+='</svg>';
  return s;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { nqSolve:nqSolve, nqValidate:nqValidate, nqCounts:nqCounts, nqSvg:nqSvg };
}
if (typeof window !== 'undefined') {
  window.NqueenForgePure = { nqSolve:nqSolve, nqValidate:nqValidate, nqCounts:nqCounts, nqSvg:nqSvg };
}
